INTERLIS 2.3;


CONTRACTED MODEL ModelA AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" =

  PARAMETER
  	RuntimeParam : TEXT;

  TOPIC TopicA = 

    CLASS ClassA =
      attr : TEXT;
      MANDATORY CONSTRAINT attr==PARAMETER RuntimeParam;
    END ClassA;

  END TopicA;

END ModelA.

INTERLIS 2.3;


MODEL ModelA AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" =


  TOPIC TopicA = 

    CLASS ClassA =
      attr : TEXT;
      MANDATORY CONSTRAINT INTERLIS.isOfClass(THIS,>ClassA);
    END ClassA;

  END TopicA;

END ModelA.

INTERLIS 2.3;

MODEL ModelA (de) AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" =

	PARAMETER 
		paramA1 : TEXT*20;
		paramA3 : MANDATORY TEXT*20;

END ModelA.


MODEL ModelB (fr) AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" 
TRANSLATION OF ModelA [ "1"]
=
	PARAMETER 
		paramB1 : TEXT*20;
		paramB3 : MANDATORY TEXT*20;

END ModelB.

INTERLIS 2.3;

MODEL model AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" =

	TOPIC topic =

		CLASS a =
		END a;

		CLASS b =
		END b;

		ASSOCIATION a2b =
			a -- a;
			b -- b;
			objClass(TRANSIENT): CLASS := INTERLIS.myClass(a);
			attrPath: ATTRIBUTE OF objClass;
		END a2b;

	END topic;

END model.

INTERLIS 2.3;

CONTRACTED MODEL ModelA (de) AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" =

	TOPIC TopicA =

		CLASS ClassA =
			attrA1 : ATTRIBUTE;
			attrA2 : ATTRIBUTE RESTRICTION (TEXT*10);
			attrA3 : CLASS;
			attrA4 : ATTRIBUTE OF attrA3;
		END ClassA;

	END TopicA;

	FUNCTION funcA (argA1: OBJECTS OF ANYCLASS; argA2: ATTRIBUTE OF @ argA1): BOOLEAN;

END ModelA.

CONTRACTED MODEL ModelB (fr) AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" 
TRANSLATION OF ModelA [ "1"]
=

	TOPIC TopicB =

		CLASS ClassB =
			attrB1 : ATTRIBUTE;
			attrB2 : ATTRIBUTE RESTRICTION (TEXT*10);
			attrB3 : CLASS;
			attrB4 : ATTRIBUTE OF attrB3;
		END ClassB;

	END TopicB;

	FUNCTION funcB (argB1: OBJECTS OF ANYCLASS; argB2: ATTRIBUTE OF @ argB1): BOOLEAN;

END ModelB.

INTERLIS 2.3;

CONTRACTED MODEL model AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" =
	FUNCTION func(Objects: OBJECTS OF ANYCLASS;
		attrPath: ATTRIBUTE OF @ Objects
		): BOOLEAN;

END model.

INTERLIS 2.3;


MODEL ModelA AT "http://www.interlis.ch/ili2c/tests/" VERSION "1" =


  TOPIC TopicA = 

    CLASS ClassA =
      attr1 : ATTRIBUTE;
      attr2 : TEXT;
      MANDATORY CONSTRAINT attr1==>>attr2;
    END ClassA;

  END TopicA;

END ModelA.

INTERLIS 2.3;

CONTRACTED MODEL model 
	AT "http://www.interlis.ch/ili2c/tests/" 
	VERSION "1" =

	FUNCTION func( Objects : OBJECTS OF ANYCLASS; attrPath : ATTRIBUTE OF @ Objects) : BOOLEAN;

	TOPIC topic =

		CLASS a =
			objClass : CLASS;
			attrPath : ATTRIBUTE OF objClass;
			attrPath2 : ATTRIBUTE RESTRICTION ( TEXT*10 );
		END a;

	END topic;

END model.
